        ["La moitié de vos morts sont des travaux de groupe : %s pour %s."] = "La mitad de tus muertes fueron trabajos en grupo: %s por %s.",
        ["Vos ennemis ne sortent jamais seuls. Vous, si : %s pour %s."] = "Tus enemigos nunca salen solos. Tú sí: %s por %s.",
        ["Un contre un, c’est démodé, apparemment : %s pour %s."] = "El uno contra uno pasó de moda, al parecer: %s por %s.",
        ["Vous rassemblez les foules. Surtout autour de votre cadavre : %s pour %s."] = "Atraes multitudes. Sobre todo alrededor de tu cadáver: %s por %s.",
        ["Vous ne les voyez jamais venir : %s pour %s."] = "Nunca los ves venir: %s por %s.",
        ["Le premier coup est toujours pour vous, et pas dans le bon sens : %s pour %s."] = "El primer golpe siempre es para ti, y no en el buen sentido: %s por %s.",
        ["Regardez derrière vous. Non, encore plus derrière : %s pour %s."] = "Mira detrás de ti. No, más atrás: %s por %s.",
        ["Surpris en train de miner, de pêcher, de manger : %s pour %s."] = "Sorprendido minando, pescando, comiendo: %s por %s.",
        ["Vos ennemis adorent les surprises. Vous, de moins en moins : %s pour %s."] = "A tus enemigos les encantan las sorpresas. A ti, cada vez menos: %s por %s.",
        ["Quelqu’un vous a pris en affection, et ça fait mal : %s pour %s."] = "Alguien te tomó cariño, y duele: %s por %s.",
        ["Une seule personne a fait la moitié du travail : %s pour %s."] = "Una sola persona hizo la mitad del trabajo: %s por %s.",
        ["Vous avez un admirateur. Il s’exprime à coups d’épée : %s pour %s."] = "Tienes un admirador. Se expresa a espadazos: %s por %s.",
