        ["Cochée : la carte montre vos combats et ceux de la guilde. Décochée : les vôtres seulement. Ce filtre ne change rien à ce que vous partagez."] = "Marcada: el mapa muestra tus combates y los de la hermandad. Desmarcada: solo los tuyos. Este filtro no cambia nada de lo que compartes.",
        ["Vos victoires et vos morts, avec leur lieu, dans le Journal de guilde et sur la carte des membres, et vos scores pour les primes. Décochée : rien n’est envoyé, et vous ne voyez plus les combats des autres."] = "Tus victorias y tus muertes, con su lugar, en el diario de hermandad y en el mapa de los miembros, y tus marcadores para las recompensas. Desmarcada: no se envía nada y ya no ves los combates de los demás.",
