        ["INDISPONIBLE : Minimap:IsMouseOver absent."] = "NO DISPONIBLE: falta Minimap:IsMouseOver.",
        ["Icônes et couleurs activées, mais le jeu n'a pas confirmé toutes les barres de noms. Vérifiez les réglages d'affichage."] = "Los iconos y colores están activos. Revisa los ajustes de visualización: no se han podido verificar todas las placas.",
