        ["Joueur connu"] = "Jugador conocido",
        ["Journal"] = "Diario",
        ["Journal de combat : coup fatal personnel (PARTY_KILL)."] = "Registro de combate: diste el golpe de gracia (PARTY_KILL).",
        ["Le jeu vous attribue le coup fatal (PARTY_KILL)."] = "El juego te atribuye el golpe de gracia (PARTY_KILL).",
        ["Le jeu a attribué le coup fatal à un autre joueur."] = "El juego atribuyó el golpe de gracia a otro jugador.",
        ["Votre familier a porté le coup fatal à ce joueur."] = "Tu mascota dio el golpe de gracia a este jugador.",
        ["Achevé par un monstre pendant votre combat : aucun autre joueur ne lui a porté le coup fatal."] = "Rematado por un monstruo durante tu combate: ningún otro jugador le dio el golpe de gracia.",
        ["Effet néfaste posé sur vous par ce joueur hostile pendant le combat."] = "Este jugador hostil te aplicó un efecto perjudicial durante el combate.",
        ["Agression non comptée : un monstre vous attaquait aussi"] = "Agresión no contada: un monstruo también te atacaba",
        ["Le journal de combat vous attribue les dégâts mortels."] = "El registro de combate te atribuye el daño letal.",
        ["Journal de combat : dégâts létaux explicitement attribués à ce joueur."] = "Registro de combate: daño letal atribuido expresamente a este jugador.",
        ["Journal de combat : dégâts reçus de ce joueur hostile (%s)."] = "Registro de combate: daño recibido de este jugador hostil (%s).",
        ["Journal des détections"] = "Registro de detecciones",
        ["Journal local : contient les noms de votre livre. Ne le publiez pas tel quel."] = "Diario local: contiene nombres de jugadores. Ocúltalos antes de compartirlo.",
        ["La chronique de vos rencontres"] = "Crónica de tus encuentros",
        ["La cible est un joueur, mais son identité n'a pas pu être lue. Aucun point n'a été testé."] = "No se pudo leer la identidad del jugador. No se comprobó ningún punto.",
        ["La cible est un joueur, mais son prénom ou son nom de famille est indisponible. Aucun point n'a été testé."] = "El nombre o el apellido del jugador no está disponible. No se comprobó ningún punto.",
        ["La cible n'est pas un joueur. Choisissez un joueur comme témoin, pas un PNJ ni un familier."] = "Elige a un jugador como referencia. Los PNJ y las mascotas no sirven de referencia.",
        ["La minimap n'est pas visible."] = "El minimapa está oculto.",
        ["La note est trop longue (2000 octets maximum)."] = "Nota demasiado larga (máximo 2000 bytes).",
        ["La note est vide."] = "La nota está vacía.",
        ["La note n’a pas pu être enregistrée."] = "No se ha podido guardar la nota.",
        ["La position, l'echelle ou le zoom de la minimap a change, ou est protege."] = "La posición, la escala o el zoom del minimapa ha cambiado o está protegido.",
        ["La souris est revenue sur la minimap pendant la relecture."] = "El cursor volvió al minimapa durante la segunda lectura.",
        ["Le /spit natif peut rester un crachat au sol : le jeu décide du texte reçu, même avec une cible."] = "El gesto /spit puede escupir al suelo. El juego decide el mensaje incluso con un jugador seleccionado.",
        ["Le Journal rassemble vos avis, vos notes et votre histoire. Partager un groupe ne crée pas d’amitié."] = "El diario reúne tus opiniones, notas e historial. Compartir grupo no convierte a nadie en amigo.",
        ["Le clic droit sur le portrait permet aussi de choisir un statut."] = "También puedes hacer clic derecho en el retrato para elegir una valoración.",
        ["Le familier de ce joueur vous a porté le coup fatal."] = "La mascota de este jugador te dio el golpe de gracia.",
        ["Le familier de ce joueur vous ciblait en combat juste avant votre mort. Le coup fatal reste incertain."] = "La mascota de este jugador te tenía como objetivo justo antes de tu muerte. No se sabe quién dio el golpe de gracia.",
        ["Le jeu a refusé le geste. Aucun avis ajouté."] = "El juego rechazó el gesto. No se registró ninguna opinión.",
        ["Le jeu ne fournit pas une vitesse lisible."] = "El juego no proporcionó una velocidad legible.",
        ["Le journal de combat attribue les dégâts au familier de ce joueur."] = "El registro de combate atribuye el daño a la mascota de este jugador.",
        ["Le plus d'agressions"] = "Más agresiones contra ti",
        ["Le plus d'amis"] = "Más amistades",
        ["Le plus de rancunes"] = "Más rencores",
        ["Le plus vaincu"] = "Rival más derrotado",
        ["Le registre compte aussi "] = "El registro también recoge ",
        ["Le repérage utilise les barres de nom compatibles."] = "Los marcadores usan placas de nombre compatibles.",
        ["Le récapitulatif attribue les dégâts au familier de ce joueur."] = "El resumen de muerte atribuye el daño a la mascota de este jugador.",
        ["Le récit de cette période reste à écrire."] = "El relato de este periodo sigue por escribir.",
        ["Le témoin persiste sur un point vide : cache possible, résultat non validé."] = "La referencia persiste en un punto vacío. Posible resultado en caché.",
        ["Lecture : %d %%"] = "Tamaño del texto: %d %%",
        ["Les amis actuels avec lesquels vous avez partagé le plus de sessions de groupe."] = "Amigos con los que más veces has formado grupo.",
        ["Les amis avec lesquels vous avez passé le plus de temps en groupe, tous deux en ligne."] = "Amigos con los que más tiempo has pasado en grupo, con ambos en línea.",
        ["Les avis de guilde que vous avez enregistrés, par ordre alphabétique."] = "Tus opiniones de hermandad, por orden alfabético.",
        ["Les avis individuels restent prioritaires. La fiche indique les exceptions à la règle choisie."] = "Las opiniones individuales tienen prioridad. La ficha de la hermandad muestra las excepciones a su regla.",
        ["Les avis, les gestes et les faits PvP alimentent le solde. Un ami désigné par un avis de guilde peut avoir un solde nul."] = "Las opiniones, los gestos y los encuentros JcJ influyen en el saldo. Un amigo marcado por su hermandad puede tener un saldo de cero.",
        ["La race et la classe sont celles relevées au combat. « Inconnue » signifie que l'information manque."] = "La raza y la clase se registraron en combate. «Desconocida» indica que faltaba ese dato.",
        ["Les durées commencent lorsque le suivi observe les deux joueurs connectés. Les anciennes sessions et les champs de bataille sont exclus du calcul."] = "Se mide el tiempo mientras ambos jugadores están en línea. Se excluyen los campos de batalla y las sesiones anteriores al seguimiento.",
        ["Les gestes sortants ne sont pas disponibles : hooksecurefunc absent."] = "Los gestos enviados no están disponibles: falta hooksecurefunc.",
        ["Les guildes de votre histoire"] = "Hermandades de tu diario",
        ["Nombre de vos morts auxquelles chaque adversaire a participé."] = "Número de muertes tuyas en las que participó cada rival.",
        ["Plusieurs adversaires peuvent participer au même combat. Le coup fatal est indiqué lorsqu’il est connu."] = "Varios rivales pueden participar en un combate. Si se conoce el golpe de gracia, se indica en el registro.",
        ["Les joueurs avec le plus d'agressions enregistrées à votre encontre."] = "Jugadores con más agresiones contra ti.",
        ["Les joueurs contre lesquels vous avez le plus de victoires."] = "Jugadores a los que más veces has derrotado en combate.",
        ["Les membres héritent de l'avis de leur guilde. Un choix personnel reste prioritaire."] = "Los miembros heredan la opinión de su hermandad. Tu opinión personal tiene prioridad.",
        ["Ce classement commence à la deuxième rencontre observée sur le compte."] = "Esta clasificación empieza en el segundo encuentro registrado en la cuenta.",
        ["Les personnages de ce compte"] = "Personajes de esta cuenta",
        ["Les rancunes restent tenaces : une mort pèse bien plus qu’une victoire. Un avis manuel ou de guilde peut aussi signaler un danger sans solde négatif."] = "Una muerte pesa mucho más que una victoria. Una opinión personal o de hermandad también puede señalar un peligro con independencia del saldo.",
        ["Les traces privées peuvent contenir des noms."] = "Los registros privados pueden contener nombres.",
        ["Les victoires compensent la dette de PvP. Seul un avis positif peut créer une amitié."] = "Las victorias reducen la deuda JcJ. Para entablar amistad hace falta una opinión positiva.",
        ["Les émotes ne sont pas disponibles sur ce client."] = "Los gestos no están disponibles en este cliente.",
