        ["Radar druide en recherche. L’essai manuel reste accessible dans le diagnostic."] = "El radar de druida es experimental. Puedes hacer una prueba manual desde Diagnóstico.",
        ["Radar druide · addon %s · build %s · %s · %s\n%s%s\n%d points, %d lectures, %d textes distincts, %d correspondances connues, %.1f s.\n%d points ignorés : élément de la minimap sous la souris."] = "Radar de druida · addon %s · compilación %s · %s · %s\n%s%s\n%d puntos, %d lecturas, %d textos distintos, %d coincidencias conocidas, %.1f s.\n%d puntos omitidos porque había un elemento del minimapa bajo el cursor.",
        ["Rancune de guilde : %s"] = "Rencor de hermandad: %s",
