        ["Rancunes personnelles"] = "Rencores personales",
        ["Rapport anonyme : Ctrl+C pour copier. Aucun nom ni note personnelle."] = "Informe anónimo. Pulsa Ctrl+C para copiar. No incluye nombres de jugadores ni notas personales.",
