        ["Repérage activé : barres de noms, icônes et couleurs. Ennemi = rouge, méfiance = orange."] = "Marcadores activados: placas, iconos y colores. Rojo = enemigo, naranja = en observación.",
        ["Restauration incomplète : utilisez /reload avant un nouvel essai."] = "Restauración incompleta. Usa /reload antes de otra prueba.",
        ["Retrouvez ce guide dans les réglages, sous Données et diagnostic."] = "Puedes volver a abrir esta guía en Ajustes, en Datos y diagnóstico.",
