        ["Reçu : %s"] = "Recibido: %s",
        ["Réapplication native indisponible sur ce client. Aucun essai lancé."] = "Este cliente no puede restaurar el ajuste nativo del minimapa. La prueba no se ha iniciado.",
        ["Réapplique l'apparence native ; rotation conservée."] = "Restaura el aspecto original y conserva el ajuste de rotación.",
