        ["Le Miroir %s"] = "The Mirror %s",
        ["Le cimetière a perdu votre adresse : trop peu de combats pour vous juger."] = "The graveyard lost your address: too few fights to judge you.",
        ["Votre épée est restée au fourreau. Votre monture, elle, a beaucoup travaillé."] = "Your sword stayed sheathed. Your mount, on the other hand, worked hard.",
        ["%d fois, vous leur avez rendu la monnaie de leur pièce. Avec les intérêts."] = "%d times you paid them back in kind. With interest.",
        ["Le cimetière vous renvoie, vous renvoyez l’addition : %d revanches."] = "The graveyard sends you back, you send the bill: %d revenge wins.",
        ["Vous préparez le terrain, les autres signent le coup final : %d assistances."] = "You do the groundwork, others land the killing blow: %d assists.",
        ["%d assistances : vous tapez, ils encaissent l’honneur."] = "%d assists: you hit, they cash in the honor.",
        ["Toujours là au bon moment, jamais pour le coup final : %d assistances."] = "Always there at the right moment, never for the final blow: %d assists.",
        ["%d fois, vous avez fait le gros du travail. Les autres ont pris la photo."] = "%d times you did the heavy lifting. Others took the photo.",
        ["Sans vous, %d ennemis seraient encore debout. Personne ne vous remerciera."] = "Without you, %d enemies would still be standing. Nobody will thank you.",
        ["Minuit passé, et vous êtes encore là : %s pour %s."] = "Past midnight and still out there: %s for %s.",
        ["Les honnêtes gens dorment. Vous, vous comptez : %s pour %s."] = "Decent folk are asleep. You are keeping score: %s for %s.",
        ["Bilan nocturne : %s et %s. Le réveil va piquer."] = "Night shift report: %s and %s. The alarm clock will hurt.",
        ["Entre minuit et l’aube, %s pour %s. Votre lit vous attend toujours."] = "Between midnight and dawn, %s for %s. Your bed is still waiting.",
        ["La lune a tout vu : %s pour %s. Elle ne dira rien."] = "The moon saw it all: %s for %s. It will not tell.",
        ["Vous ouvrez le bal, vous fermez le cercueil : %s pour %s."] = "You open the dance, you close the coffin: %s for %s.",
        ["Premier coup, dernier mot : %s pour %s."] = "First hit, last word: %s for %s.",
        ["Vos adversaires visitent le cimetière plus souvent que vous : %s pour %s."] = "Your foes visit the graveyard more than you do: %s for %s.",
        ["Vous choisissez des adversaires à votre taille. En plus petit : %s pour %s."] = "You pick on someone your own size. Only smaller: %s for %s.",
        ["%s pour %s, surtout contre des niveaux plus bas. Le courage a ses limites."] = "%s for %s, mostly against lower levels. Courage has its limits.",
        ["Les nouveaux venus vous connaissent bien : %s pour %s."] = "The newcomers know you well: %s for %s.",
        ["Victoires faciles, honneur discutable : %s pour %s."] = "Easy wins, questionable honor: %s for %s.",
        ["Vous gagnez surtout contre plus petit que vous : %s pour %s. Leurs grands frères arrivent."] = "You mostly beat smaller foes: %s for %s. Their big brothers are coming.",
        ["Plus ils sont grands, plus ils tombent de haut : %s pour %s."] = "The bigger they are, the harder they fall: %s for %s.",
        ["Le niveau n’est qu’un chiffre, et vous le prouvez : %s pour %s."] = "Level is just a number, and you prove it: %s for %s.",
        ["Vous tapez au-dessus de votre catégorie : %s pour %s."] = "You punch above your weight: %s for %s.",
        ["Eux avaient les niveaux, vous aviez l’audace : %s pour %s."] = "They had the levels, you had the nerve: %s for %s.",
        ["Quelque part, un gros niveau se demande encore ce qui s’est passé : %s pour %s."] = "Somewhere, a high level is still wondering what happened: %s for %s.",
        ["Seul on va vite, ensemble on gagne : %s pour %s."] = "Alone you go fast, together you win: %s for %s.",
        ["La moitié de vos victoires se fêtent à plusieurs : %s pour %s."] = "Half your wins are group celebrations: %s for %s.",
        ["Vos amis tapent, vous tapez, l’ennemi s’allonge : %s pour %s."] = "Your friends hit, you hit, the enemy lies down: %s for %s.",
        ["Le fair-play, c’est surfait. Le nombre, c’est efficace : %s pour %s."] = "Fair play is overrated. Numbers work: %s for %s.",
        ["En groupe, vous êtes redoutable. Seul, on verra : %s pour %s."] = "In a group, you are fearsome. Alone, we shall see: %s for %s.",
        ["Vous attaquer est une mauvaise idée, les chiffres le disent : %s pour %s."] = "Attacking you is a bad idea, the numbers say so: %s for %s.",
        ["Ils frappent les premiers, vous frappez les derniers : %s pour %s."] = "They strike first, you strike last: %s for %s.",
        ["Vous tendre une embuscade, c’est un aller simple pour le cimetière : %s pour %s."] = "Ambushing you is a one-way ticket to the graveyard: %s for %s.",
        ["Les grands de la cour vous ont repéré : %s pour %s."] = "The big kids on the playground spotted you: %s for %s.",
        ["Ils ont plus de niveaux, plus d’équipement et aucune pitié : %s pour %s."] = "They have more levels, better gear and no mercy: %s for %s.",
        ["Vous mourez surtout contre plus grand que vous : %s pour %s. Grandissez vite."] = "You mostly die to bigger players: %s for %s. Grow up fast.",
        ["Le niveau n’est qu’un chiffre. Le leur est juste plus gros : %s pour %s."] = "Level is just a number. Theirs is just bigger: %s for %s.",
        ["Un jour vous serez grand, et ils auront intérêt à courir : %s pour %s."] = "One day you will be big, and they had better run: %s for %s.",
        ["Ils étaient plusieurs, vous étiez seul : %s pour %s."] = "There were several of them, and just you: %s for %s.",
        ["La moitié de vos morts sont des travaux de groupe : %s pour %s."] = "Half your deaths were group projects: %s for %s.",
        ["Vos ennemis ne sortent jamais seuls. Vous, si : %s pour %s."] = "Your enemies never go out alone. You do: %s for %s.",
        ["Un contre un, c’est démodé, apparemment : %s pour %s."] = "One on one is out of fashion, apparently: %s for %s.",
        ["Vous rassemblez les foules. Surtout autour de votre cadavre : %s pour %s."] = "You draw a crowd. Mostly around your corpse: %s for %s.",
        ["Vous ne les voyez jamais venir : %s pour %s."] = "You never see them coming: %s for %s.",
        ["Le premier coup est toujours pour vous, et pas dans le bon sens : %s pour %s."] = "The first hit is always yours, and not in a good way: %s for %s.",
        ["Regardez derrière vous. Non, encore plus derrière : %s pour %s."] = "Look behind you. No, further behind: %s for %s.",
        ["Surpris en train de miner, de pêcher, de manger : %s pour %s."] = "Caught mining, fishing, eating: %s for %s.",
        ["Vos ennemis adorent les surprises. Vous, de moins en moins : %s pour %s."] = "Your enemies love surprises. You, less and less: %s for %s.",
        ["Quelqu’un vous a pris en affection, et ça fait mal : %s pour %s."] = "Someone has taken a liking to you, and it hurts: %s for %s.",
        ["Une seule personne a fait la moitié du travail : %s pour %s."] = "One single person did half the work: %s for %s.",
        ["Vous avez un admirateur. Il s’exprime à coups d’épée : %s pour %s."] = "You have an admirer. They express it with a sword: %s for %s.",
        ["Toujours le même nom dans votre journal des morts : %s pour %s."] = "Always the same name in your death log: %s for %s.",
        ["Ce n’est plus un ennemi, c’est une habitude : %s pour %s."] = "That is no longer an enemy, that is a habit: %s for %s.",
        ["Un seul endroit, la moitié de vos morts : %s pour %s. Évitez le coin."] = "One place, half your deaths: %s for %s. Avoid the area.",
        ["Vous aimez ce coin. Lui aussi, il aime vous voir mourir : %s pour %s."] = "You love this place. It loves watching you die: %s for %s.",
        ["Ce lieu est maudit, et vous y retournez quand même : %s pour %s."] = "This place is cursed, and you keep going back: %s for %s.",
        ["Le cimetière du coin vous réserve une place : %s pour %s."] = "The local graveyard saves you a spot: %s for %s.",
        ["Il existe d’autres zones en Azeroth, promis : %s pour %s."] = "There are other zones in Azeroth, we promise: %s for %s.",
        ["Votre armure passe plus de temps chez le réparateur que sur vous : %s pour %s."] = "Your armor spends more time at the repair vendor than on you: %s for %s.",
        ["Un coup pour vous, un coup pour eux. Le cimetière reste neutre : %s, %s."] = "One for you, one for them. The graveyard stays neutral: %s, %s.",
        ["Ni héros ni victime : %s et %s. La suite au prochain épisode."] = "Neither hero nor victim: %s and %s. To be continued.",
