        ["Les avis de guilde que vous avez enregistrés, par ordre alphabétique."] = "Your saved guild opinions, in alphabetical order.",
        ["Les avis individuels restent prioritaires. La fiche indique les exceptions à la règle choisie."] = "Individual opinions take precedence. The guild profile lists exceptions to its rule.",
        ["Les avis, les gestes et les faits PvP alimentent le solde. Un ami désigné par un avis de guilde peut avoir un solde nul."] = "Opinions, emotes and PvP encounters affect this balance. A friend marked through a guild opinion can have a balance of zero.",
